  'involved.label': { en: 'Join Our Mission', fr: 'Rejoignez Notre Mission', kw: 'Injira mu Ntego Yacu' },
  'involved.title': { en: 'Get Involved', fr: 'S\'Impliquer', kw: 'Twitabaza' },
  'involved.sub': { en: 'Whether you volunteer, fundraise, or partner with us — your involvement helps more families in Rwanda receive the support they need.', fr: 'Que vous fassiez du bénévolat, collectiez des fonds ou que vous soyez partenaire avec nous — votre implication aide plus de familles au Rwanda à recevoir le soutien dont elles ont besoin.', kw: 'Haba ubashake, gukusanya inkunga, cyangwa gufatanya natwe — kwitabaza kwawe bifasha imiryango myinshi mu Rwanda guhabwa inkunga ikeneye.' },
  'involved.cta.getintouch': { en: 'Get in Touch', fr: 'Nous Contacter', kw: 'Dutumanahane' },
  'involved.ways.label': { en: 'How You Can Help', fr: 'Comment Vous Pouvez Aider', kw: 'Uburyo Mushobora Gufasha' },
  'involved.ways.title': { en: 'Ways to get involved', fr: 'Façons de s\'impliquer', kw: 'Inzira zo kwitabaza' },
  'involved.express': { en: 'Express interest', fr: 'Exprimer son intérêt', kw: 'Erekana inyungu' },
  'involved.w1.title': { en: 'Volunteer', fr: 'Bénévolat', kw: 'Ikipe y\'Ubushake' },
  'involved.w1.desc': { en: 'Give your time and skills to support premature babies and their families. We need passionate people in many roles.', fr: 'Donnez votre temps et vos compétences pour soutenir les bébés prématurés et leurs familles. Nous avons besoin de personnes passionnées dans de nombreux rôles.', kw: 'Tanga igihe n\'ubushobozi bwawe gufasha abana bavutse mbere y\'igihe n\'imiryango yabo. Dukeneye abantu binyuza mu bikorwa byinshi.' },
  'involved.w1.r1': { en: 'Peer support mentor (training provided)', fr: 'Mentor de soutien par les pairs (formation fournie)', kw: 'Umuyigisha w\'inkunga y\'inshuti (amahugurwa atangwa)' },
  'involved.w1.r2': { en: 'Event coordinator', fr: 'Coordinateur d\'événements', kw: 'Umutonganyi w\'ibikorwa' },
  'involved.w1.r3': { en: 'Administrative support', fr: 'Soutien administratif', kw: 'Inkunga y\'ubutegetsi' },
  'involved.w1.r4': { en: 'Translator (French, Kinyarwanda)', fr: 'Traducteur (Français, Kinyarwanda)', kw: 'Umuhinduzi (Igifaransa, Ikinyarwanda)' },
  'involved.w1.r5': { en: 'Social media and communications', fr: 'Médias sociaux et communications', kw: 'Imiyoboro nyamuntu n\'itumanahano' },
  'involved.w1.r6': { en: 'Healthcare professional volunteer', fr: 'Bénévole professionnel de santé', kw: 'Inzobere mu ubuvuzi y\'ubushake' },
  'involved.w2.title': { en: 'Fundraise', fr: 'Collecter des Fonds', kw: 'Gukusanya Inkunga' },
  'involved.w2.desc': { en: 'Run your own campaign to raise funds for Voice of Preemies. Challenge yourself, engage your community, and make an impact.', fr: 'Lancez votre propre campagne pour collecter des fonds pour Voice of Preemies. Défiez-vous, engagez votre communauté et ayez un impact.', kw: 'Fata inkunga yawe kugira ngo ukusanye inkunga ya Voice of Preemies. Wiyorobere, witabaza umuryango wawe, ukore ingaruka.' },
  'involved.w2.r1': { en: 'Birthday or celebration donation drive', fr: 'Collecte de dons d\'anniversaire ou de célébration', kw: 'Gukusanya impano z\'ubuzahanye cyangwa ibirori' },
  'involved.w2.r2': { en: 'Workplace giving campaign', fr: 'Campagne de dons en milieu de travail', kw: 'Gahunda yo gutanga mu kazi' },
  'involved.w2.r3': { en: 'Marathon or sports challenge', fr: 'Marathon ou défi sportif', kw: 'Marathon cyangwa gushidikanya kw\'imikino' },
