  'involved.w3.title': { en: 'Become a Partner', fr: 'Devenir Partenaire', kw: 'Fata Inkunga Natwe' },
  'involved.w3.desc': { en: 'Organizations, hospitals, and businesses can partner with us to extend our reach and co-create impact in Rwanda.', fr: 'Les organisations, les hôpitaux et les entreprises peuvent être partenaires avec nous pour étendre notre portée et co-créer de l\'impact au Rwanda.', kw: 'Imiryango, ibitaro, n\'ibigo bishobora gufatanya natwe kongera inzira zacu no gushirikirana ingaruka mu Rwanda.' },
  'involved.w3.r1': { en: 'Hospital / NICU partnership', fr: 'Partenariat Hôpital / NICU', kw: 'Ubufatanye bw\'Ibitaro / NICU' },
  'involved.w3.r2': { en: 'NGO collaboration', fr: 'Collaboration ONG', kw: 'Gufatanya na ONG' },
