  'involved.w4.title': { en: 'Corporate Support', fr: 'Soutien d\'Entreprise', kw: 'Inkunga y\'Ibigo' },
  'involved.w4.desc': { en: 'Corporate sponsorship and CSR partnerships help us scale our programs and reach more families across Rwanda.', fr: 'Le parrainage d\'entreprise et les partenariats RSE nous aident à développer nos programmes et à atteindre plus de familles à travers le Rwanda.', kw: 'Ubufatanye n\'ibigo na CSR bifasha gukura gahunda zacu no kugera ku miryango myinshi mu Rwanda hose.' },
