  'involved.wpd.date': { en: 'November 17', fr: '17 Novembre', kw: 'Ugushyingo 17' },
  'involved.wpd.title': { en: 'World Prematurity Day', fr: 'Journée Mondiale de la Prématurité', kw: 'Umunsi wa Prematurity ku Isi' },
  'involved.wpd.sub': { en: 'Join us every November 17 to raise awareness about prematurity in Rwanda. Wear purple, share stories, and make some noise for every preemie.', fr: 'Rejoignez-nous chaque 17 novembre pour sensibiliser à la prématurité au Rwanda. Portez du violet, partagez des histoires et faites du bruit pour chaque prématuré.', kw: 'Twitabaze buri Ugushyingo 17 kugira ngo tukangurire ku kuvuka mbere y\'igihe mu Rwanda. Ambara ibiranga, sangira inkuru, ukangure amajwi ku mwana wese wavutse mbere y\'igihe.' },
