  // ─── NEWS PAGE ────────────────────────────────────────────────────────────────
  'news.featured.tag': { en: 'Event', fr: 'Événement', kw: 'Igikorwa' },
  'news.featured.title': { en: 'World Prematurity Day 2024: Thousands Join Rwanda\'s Largest Preemie Awareness Campaign', fr: 'Journée Mondiale de la Prématurité 2024: Des Milliers Rejoignent la Plus Grande Campagne de Sensibilisation du Rwanda', kw: 'Umunsi wa Prematurity ku Isi 2024: Ibihumbi Byinjira mu Gahunda Nkuru Cyane y\'u Rwanda' },
  'news.featured.excerpt': { en: 'On November 17, 2024, Voice of Preemies led Rwanda\'s most visible World Prematurity Day campaign to date — bringing together families, healthcare professionals, hospital administrators, and government representatives in a day of education, advocacy, and celebration of preemie life.', fr: 'Le 17 novembre 2024, Voice of Preemies a dirigé la campagne de la Journée Mondiale de la Prématurité la plus visible du Rwanda à ce jour — réunissant des familles, des professionnels de santé, des administrateurs d\'hôpitaux et des représentants du gouvernement dans une journée d\'éducation, de plaidoyer et de célébration de la vie des prématurés.', kw: 'Ku wa 17 Ugushyingo 2024, Voice of Preemies yayoboye gahunda ya Umunsi wa Prematurity ku Isi yabonekaga cyane kuruta indi yose mu Rwanda — iteranye imiryango, inzobere mu ubuvuzi, abakozi b\'ibitaro, n\'inzego za leta mu munsi w\'uburezi, kuvugira, no guhimbaza ubuzima bw\'abavutse mbere y\'igihe.' },
  'news.a1.tag': { en: 'Partnership', fr: 'Partenariat', kw: 'Ubufatanye' },
  'news.a1.title': { en: 'Voice of Preemies Expands Hospital Program to CHUK\'s Neonatal Unit', fr: 'Voice of Preemies Étend son Programme Hospitalier à l\'Unité Néonatale du CHUK', kw: 'Voice of Preemies Yagutiye Gahunda y\'Ibitaro ku Saha ya CHUK' },
  'news.a1.excerpt': { en: 'Our NICU family guidance program is now officially embedded within CHUK\'s neonatal intensive care unit, reaching an additional 80+ families per month.', fr: 'Notre programme d\'orientation familiale NICU est maintenant officiellement intégré dans l\'unité de soins intensifs néonatals du CHUK, atteignant 80+ familles supplémentaires par mois.', kw: 'Gahunda yacu yo kuyobora umuryango wa NICU ubu ari mu saha y\'ubuvuzi bw\'impinja bwa CHUK, igera ku miryango 80+ inyongera buri kwezi.' },
  'news.a2.tag': { en: 'Story', fr: 'Témoignage', kw: 'Inkuru' },
  'news.a2.title': { en: 'Amina\'s Journey: How Peer Support Changed Everything', fr: 'Le Parcours d\'Amina: Comment le Soutien par les Pairs a Tout Changé', kw: 'Urugendo rwa Amina: Uburyo Inkunga y\'Inshuti Yahindura Byose' },
  'news.a2.excerpt': { en: 'A mother\'s story of navigating 6 weeks in the NICU with Voice of Preemies by her side.', fr: 'L\'histoire d\'une mère naviguant 6 semaines dans le NICU avec Voice of Preemies à ses côtés.', kw: 'Inkuru y\'umubyeyi wo gukora ibyumweru 6 mu NICU hamwe na Voice of Preemies iruhande rwe.' },
  'news.a3.tag': { en: 'Research', fr: 'Recherche', kw: 'Ubushakashatsi' },
  'news.a3.title': { en: 'New Study: Family Support in Rwandan NICUs Improves Outcomes', fr: 'Nouvelle Étude: Le Soutien Familial dans les NICU Rwandais Améliore les Résultats', kw: 'Ubushakashatsi Bushya: Inkunga y\'Umuryango mu NICU z\'u Rwanda Inonosora Imiterere' },
  'news.a3.excerpt': { en: 'A collaborative study with CHUK shows that families who received peer support stayed more engaged in KMC, leading to faster weight gain.', fr: 'Une étude collaborative avec le CHUK montre que les familles ayant reçu un soutien par les pairs sont restées plus engagées dans le KMC, entraînant une prise de poids plus rapide.', kw: 'Ubushakashatsi bw\'ubufatanye na CHUK bugaragaza ko imiryango yabonye inkunga y\'inshuti yakomeje gukorana na KMC, bituma inyunyuto yihuta.' },
  'news.a4.tag': { en: 'Education', fr: 'Éducation', kw: 'Uburezi' },
  'news.a4.title': { en: 'New Kinyarwanda Parent Guide Now Available', fr: 'Nouveau Guide Parentaux en Kinyarwanda Maintenant Disponible', kw: 'Amabwiriza Mashya y\'Ababyeyi mu Kinyarwanda Abonetse' },
  'news.a4.excerpt': { en: 'Our comprehensive guide to prematurity and NICU care is now available in Kinyarwanda, making vital information accessible to more families.', fr: 'Notre guide complet sur la prématurité et les soins en NICU est maintenant disponible en Kinyarwanda, rendant des informations vitales accessibles à plus de familles.', kw: 'Amabwiriza yacu yuzuye ku kuvuka mbere y\'igihe no kwita mu NICU ubu abonetse mu Kinyarwanda, ategura amakuru y\'ingenzi ku miryango myinshi.' },
  'news.a5.tag': { en: 'Event', fr: 'Événement', kw: 'Igikorwa' },
  'news.a5.title': { en: 'First Annual Voice of Preemies Family Day', fr: 'Premier Jour Familial Annuel de Voice of Preemies', kw: 'Umunsi w\'Umuryango wa Voice of Preemies wa Mbere wa Buri Mwaka' },
  'news.a5.excerpt': { en: '200+ families gathered for our inaugural Family Day — a celebration of resilience, community, and the strength of preemies and their parents.', fr: '200+ familles se sont réunies pour notre première Journée Familiale — une célébration de la résilience, de la communauté et de la force des prématurés et de leurs parents.', kw: 'Imiryango 200+ yateranye ku munsi wacu wa Mbere w\'Umuryango — ibirori byo kwizirika, umuryango, n\'imbaraga z\'abavutse mbere y\'igihe n\'ababyeyi babo.' },
  'news.a6.tag': { en: 'Advocacy', fr: 'Plaidoyer', kw: 'Kuvugira' },
  'news.a6.title': { en: 'Voice of Preemies Presents at Rwanda Health Forum', fr: 'Voice of Preemies Présente au Forum de Santé du Rwanda', kw: 'Voice of Preemies Yavuganye mu Inama y\'Ubuzima y\'u Rwanda' },
  'news.a6.excerpt': { en: 'Our Executive Director presented findings on the gap in family support services in Rwanda\'s neonatal units at the national health forum.', fr: 'Notre Directeur Exécutif a présenté des conclusions sur le manque de services de soutien familial dans les unités néonatales du Rwanda au forum national de santé.', kw: 'Umuyobozi Mukuru wacu yavanaho ibintu ku ntandaro y\'inkunga y\'umuryango mu mashami y\'impinja y\'u Rwanda mu nama y\'ubuzima y\'igihugu.' },
  'news.e1.title': { en: 'World Prematurity Day 2025', fr: 'Journée Mondiale de la Prématurité 2025', kw: 'Umunsi wa Prematurity ku Isi 2025' },
  'news.e1.location': { en: 'Kigali, Rwanda', fr: 'Kigali, Rwanda', kw: 'Kigali, u Rwanda' },
  'news.e1.type': { en: 'Annual Event', fr: 'Événement Annuel', kw: 'Igikorwa cy\'Umwaka' },
