  'donate.title.em': { en: 'stronger start', fr: 'meilleur départ', kw: 'intangiriro nziza' },
  'donate.thanks.sub': { en: 'Your donation will directly support premature babies and their families in Rwanda. You will receive a confirmation by email.', fr: 'Votre don soutiendra directement les bébés prématurés et leurs familles au Rwanda. Vous recevrez une confirmation par e-mail.', kw: 'Impano yawe izashyigikira directly abana bavutse mbere y\'igihe n\'imiryango yabo mu Rwanda. Uzabona inyemezabuguzi kuri imeri.' },
  'donate.thanks.quote': { en: 'On behalf of every preemie and every family we serve — thank you.', fr: 'Au nom de chaque prématuré et de chaque famille que nous servons — merci.', kw: 'Mu izina rya buri mwana wavutse mbere y\'igihe n\'umuryango wose dukorera — urakoze.' },
