  'donate.t2.label': { en: 'Supporter', fr: 'Soutien', kw: 'Umufasha' },
  'donate.t2.desc': { en: 'Funds one peer support session for a NICU parent', fr: 'Finance une séance de soutien par les pairs pour un parent NICU', kw: 'Ishyura ikibazo kimwe cy\'inkunga y\'inshuti ku mubyeyi wa NICU' },
  'donate.t3.label': { en: 'Champion', fr: 'Champion', kw: 'Intwari' },
  'donate.t3.desc': { en: 'Sponsors a parent counseling session', fr: 'Sponsorise une séance de conseil aux parents', kw: 'Ishyura ikibazo cyo kugisha ababyeyi' },
  'donate.t4.label': { en: 'Guardian', fr: 'Gardien', kw: 'Umwungirizi' },
  'donate.t4.desc': { en: 'Supports family transport and emergency needs', fr: 'Soutient le transport familial et les besoins d\'urgence', kw: 'Ishyigikira gutwara umuryango n\'ibikenewe mu bihe bihutirwa' },
  'donate.t5.label': { en: 'Advocate', fr: 'Défenseur', kw: 'Umuvugizi' },
  'donate.t5.desc': { en: 'Funds a full month of peer support for one family', fr: 'Finance un mois complet de soutien par les pairs pour une famille', kw: 'Ishyura ukwezi kuzima kw\'inkunga y\'inshuti ku muryango umwe' },
