  'donate.other.title': { en: 'Other ways to give', fr: 'Autres façons de donner', kw: 'Inzira zindi zo gutanga' },
  'donate.o1.title': { en: 'Sponsor a Family', fr: 'Parrainer une Famille', kw: 'Shyigikira Umuryango' },
  'donate.o1.desc': { en: 'Commit to fully sponsoring one premature family\'s support journey for 3 months.', fr: 'S\'engager à parrainer entièrement le parcours de soutien d\'une famille prématurée pendant 3 mois.', kw: 'Yemera gushyigikira burundu urugendo rw\'inkunga rw\'umuryango umwe w\'umwana wavutse mbere y\'igihe mu mezi 3.' },
