  'donate.o2.desc': { en: 'Partner with us for impactful CSR initiatives that support neonatal health in Rwanda.', fr: 'Être partenaire avec nous pour des initiatives RSE impactantes qui soutiennent la santé néonatale au Rwanda.', kw: 'Fata inkunga natwe kugira ngo ugire ingaruka ku bikorwa bya CSR bishyigikira ubuzima bw\'impinja mu Rwanda.' },
